def import_content_and_results(apps, schema_editor):
    import json
    from pathlib import Path
    content = json.loads((Path(__file__).resolve().parents[1] / 'data' / 'route_scenes.json').read_text(encoding='utf-8'))
    Scene = apps.get_model('app', 'RouteSceneContent')
    alias = schema_editor.connection.alias
    Scene.objects.using(alias).bulk_create([Scene(key=k, **v) for k, v in content.items()])
    Attempt = apps.get_model('app', 'PlatformAttempt')
    def historical(kind, model, mapper, **filters):
        batch = []
        rows = apps.get_model('app', model).objects.using(alias).filter(**filters).order_by('pk')
        if kind == 'sign':
            rows = rows.select_related('sign')
        elif kind == 'practice':
            rows = rows.select_related('version__exercise')
        for obj in rows.iterator(chunk_size=500):
            task, title, score, total, date = mapper(obj)
            batch.append(Attempt(kind=kind, source=f'{kind}:{obj.pk}', user_id=obj.user_id, task=task,
                                 title=title, score=score, total=total, completed_at=date, answers=[]))
            if len(batch) == 500:
                Attempt.objects.using(alias).bulk_create(batch)
                batch.clear()
        Attempt.objects.using(alias).bulk_create(batch)
    historical('age', 'TestResult', lambda r: (r.test_type, r.get_test_type_display(), r.score,
                                                r.total_questions, r.completed_at))
    historical('route', 'RouteResult', lambda r: (r.level, content['level-' + r.level]['title'],
                                                  r.score, r.total, r.completed_at))
    historical('practice', 'PracticeResult', lambda r: (r.version.exercise_id, r.version.exercise.title,
                                                       1, 1, r.completed_at))
    historical('sign', 'UserSignProgress', lambda r: (r.sign_id, r.sign.name, 1, 1, r.test_passed_at),
               unlocked=True, test_passed_at__isnull=False)


